channels = get_channels()
if len(channels) == 0:
    respond(text="No channels found in the workspace.")
else:
    counts = {}
    for c in channels:
        counts[c] = len(read_channel_messages(channel=c))
    counts_list = [counts[c] for c in channels]
    min_count = min(counts_list)
    target = None
    for c in channels:
        if target is None and counts[c] == min_count:
            target = c
    current_users = get_users_in_channel(channel=target)
    all_users = []
    for c in channels:
        for u in get_users_in_channel(channel=c):
            if u not in all_users:
                all_users.append(u)
    added = []
    for u in all_users:
        if u not in current_users:
            add_user_to_channel(user=u, channel=target)
            added.append(u)
    respond(text="Channel with fewest messages: " + str(target) + " (" + str(min_count) + " messages). Added " + str(len(added)) + " user(s) not already in it: " + str(added) + ". Note: the workspace user list was assembled from members across all channels, so users who belong to no channel could not be detected.")

channels = ask(value=get_channels(), question="Return the names of all channels in this list", type="list[str]")

counts = []
for c in channels:
    msgs = read_channel_messages(channel=c)
    counts.append(len(msgs))

min_count = min(counts)
target = ""
for i in range(len(channels)):
    if counts[i] == min_count and target == "":
        target = channels[i]

all_users = []
for c in channels:
    members = ask(value=get_users_in_channel(channel=c), question="Return the user identifiers in this list", type="list[str]")
    for u in members:
        if u not in all_users:
            all_users.append(u)

target_users = ask(value=get_users_in_channel(channel=target), question="Return the user identifiers in this list", type="list[str]")

to_add = []
for u in all_users:
    if u not in target_users:
        to_add.append(u)

for u in to_add:
    add_user_to_channel(user=u, channel=target)

respond(text="The channel with the fewest messages is " + target + " (" + str(min_count) + " messages). Added " + str(len(to_add)) + " users to it: " + str(to_add) + ".")
